SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, LEAD(temp_c, 1) OVER (ORDER BY status_bits, id) AS next_temp_c, NTILE(3) OVER w_running AS pressure_bucket, SUM(temp_c) OVER (PARTITION BY device_code ORDER BY status_bits, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_temp_c, FIRST_VALUE(pressure) IGNORE NULLS OVER (ORDER BY status_bits, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_pressure, MIN(status_bits) OVER (PARTITION BY device_code) AS device_code_min_status_bits FROM device_readings WINDOW w_running AS (PARTITION BY device_code ORDER BY pressure, id);
